def count_roles(staff):
    x = 0
    count_a = 0
    count_b = 0
    while x < len(staff):
        if staff[x].role == "civil":
            count_a += 1
        elif staff[x].role == "company":
            count_b += 1
        x += 1
    return count_a, count_b
